.nav__brand {
  font-size: 1.25rem;
  font-weight: 600;
}

/* Links (desktop) */
.nav__links {
  list-style: none;
  display: flex;
  gap: 1.5rem;
}

.nav__links a {
  text-decoration: none;
  color: #333;
  font-size: 0.95rem;
  font-weight: 500;
}

.nav__links a:hover {
  color: #0077ff;
}

