.nav__toggle {
  display: none;
  flex-direction: column;
  justify-content: space-between;
  width: 24px;
  height: 18px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
}

.nav__toggle-line {
  width: 100%;
  height: 2px;
  background-color: #333;
  border-radius: 4px;
