#include <bits/stdc++.h>
using namespace std;

const int MAXV = 20000; // maximum possible soldier id

vector<int> adj[MAXV + 1];
bool vis[MAXV + 1];
int col[MAXV + 1];   // 0 or 1

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);

    int T;
    cin >> T;

    for (int tc = 1; tc <= T; ++tc) {
        // reset structures
        for (int i = 1; i <= MAXV; ++i) {
            adj[i].clear();
            vis[i] = false;
            col[i] = -1;
        }

        int N;
        cin >> N;

        for (int i = 0; i < N; ++i) {
            int A, B;
            cin >> A >> B;
            adj[A].push_back(B);
            adj[B].push_back(A);
        }

        int ans = 0;

        // process each connected component
        for (int i = 1; i <= MAXV; ++i) {
            if (!vis[i] && !adj[i].empty()) {
                // BFS to colour the component
                queue<int> q;
                q.push(i);
                vis[i] = true;
                col[i] = 0;
                int cnt[2] = {1, 0};   // count of vertices coloured 0 and 1

                while (!q.empty()) {
                    int u = q.front();
                    q.pop();
                    for (int v : adj[u]) {
                        if (!vis[v]) {
                            vis[v] = true;
                            col[v] = 1 - col[u];
                            cnt[col[v]]++;
                            q.push(v);
                        }
                    }
                }

                ans += max(cnt[0], cnt[1]);
            }
        }

        cout << "Case " << tc << ": " << ans << "\n";
    }

    return 0;
}
