def capitalize_words(s: str) -> str:
    """
    Capitalize the first letter of each word in the given string.
    Words are defined as sequences of non‑whitespace characters.
    All whitespace (spaces, tabs, newlines, etc.) is preserved exactly.
    """
    result = []               # store the characters of the answer
    capitalize_next = True    # flag indicating the next character should be capitalized

    for ch in s:
        if ch.isspace():
            result.append(ch)
            capitalize_next = True
        else:
            if capitalize_next:
                result.append(ch.upper())
                capitalize_next = False
            else:
                result.append(ch)

    return ''.join(result)

