```cpp
#include <bits/stdc++.h>
using namespace std;

const int MOD = 1000000007;
const int INF = 100;                  // more than maximum possible turns (≤16)

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int T;
    cin >> T;
    while (T--) {
        int N;
        cin >> N;
        vector<int> x(N), y(N);
        for (int i = 0; i < N; ++i) {
            cin >> x[i] >> y[i];
        }

        int full = (1 << N) - 1;

        // ---------- 1. precompute collinearity for every subset ----------
        vector<char> coll(1 << N, 0);
        for (int mask = 1; mask <= full; ++mask) {
            int cnt = __builtin_popcount(mask);
            if (cnt <= 2) {
                coll[mask] = 1;
                continue;
            }
            // pick the first two points
            int m = mask;
            int i = __builtin_ctz(m);  m &= m - 1;
            int j = __builtin_ctz(m);  m &= m - 1;
            int dx = x[j] - x[i];
            int dy = y[j] - y[i];
            bool ok = true;
            // check remaining points
            while (m) {
                int k = __builtin_ctz(m);
                if (dx * (y[k] - y[i]) != dy * (x[k] - x[i])) {
                    ok = false;
                    break;
                }
                m &= m - 1;
            }
            coll[mask] = ok;
        }
        coll[0] = 1;   // empty set is trivially collinear (not really used)

        // ---------- 2. DP over subsets ----------
        vector<int> turns(1 << N, INF);
        vector<int> ways(1 << N, 0);
        turns[0] = 0;
        ways[0] = 1;

        for (int mask = 1; mask <= full; ++mask) {
            if (coll[mask]) {
                turns[mask] = 1;
                ways[mask] = 1;
                continue;
            }

            int best = INF;
            long long cnt = 0;
            // iterate over all non‑empty submasks of mask
            for (int sub = mask; sub; sub = (sub - 1) & mask) {
                if (!coll[sub]) continue;
                int rest = mask ^ sub;
                int cand = 1 + turns[rest];
                if (cand < best) {
                    best = cand;
                    cnt = ways[rest];
                } else if (cand == best) {
                    cnt += ways[rest];
                }
            }
            turns[mask] = best;
            ways[mask] = cnt % MOD;
        }

        cout << turns[full] << " " << ways[full] << "\n";
    }
    return 0;
}
