### 2. Ingestion API (/api/ingest/route.ts)
```ts
import { NextRequest } from 'next/server';
import { Octokit } from '@octokit/rest';
import { db } from '@/lib/db';
import { parseDiffForDrift } from '@/lib/diff-analyzer';

export async function POST(req: NextRequest) {
  const payload = await req.json(); // GitHub webhook
  const { repo, ref, compare } = payload;

  const octokit = new Octokit({ auth: process.env.GITHUB_TOKEN });
  const { data: diff } = await octokit.rest.repos.compareCommits({
    owner: repo.owner.login,
    repo: repo.name,
    base: 'main',
    head: ref,
  });

  const drift = await parseDiffForDrift(diff.files || []);
  await db.insert(releases).values({
    id: ref,
    diff: diff,
    driftFlags: drift,
    status: 'pending',
  });

  // Slack alert
  await sendSlack(`🚨 Drift detected in ${ref}: ${drift.length} issues`);

  return Response.json({ success: true });
}
```

### 3. Drift Analyzer (lib/diff-analyzer.ts)
```ts
import * as Diff from 'diff';
import css from 'css';

export async function parseDiffForDrift(files: any[]) {
  const flags: any[] = [];
  for (const file of files.filter(f => f.filename.endsWith('.css') || f.filename.includes('component'))) {
    const oldCss = css.parse(file?.previous || '');
    const newCss = css.parse(file.patch || '');

    // Simple token check (extend for Tailwind/CSS vars)
    const changes = Diff.diffCss(oldCss.toString(), newCss.toString());
    changes.forEach(part => {
      if (part.added && part.value.includes('#')) { // Color change heuristic
        flags.push({ type: 'color-drift', file: file.filename, value: part.value });
      }
    });
  }
  // Snapshot diffs via Puppeteer/Chromatic
  return flags;
}
```

